import { useState, useEffect, useRef } from "react";

const D = {
  purple: "#6d28d9", purpleL: "#ede9fe", purpleM: "#8b5cf6",
  green: "#16a34a", greenL: "#dcfce7",
  red: "#dc2626", redL: "#fee2e2",
  amber: "#d97706", amberL: "#fef3c7",
  blue: "#2563eb", blueL: "#dbeafe",
  slate1: "#334155", slate2: "#475569", slate3: "#64748b", slate4: "#94a3b8",
  bg: "#f8fafc", card: "#ffffff", border: "#e2e8f0",
};

function useCountUp(target, duration = 1600, start = false) {
  const [val, setVal] = useState(0);
  useEffect(() => {
    if (!start) return;
    let startTime = null;
    const step = (ts) => {
      if (!startTime) startTime = ts;
      const p = Math.min((ts - startTime) / duration, 1);
      setVal(Math.floor(p * target));
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [target, duration, start]);
  return val;
}

function StatCard({ label, value, suffix = "", prefix = "", color = D.purple, start }) {
  const num = useCountUp(value, 1400, start);
  return (
    <div style={{ background: D.card, border: `1px solid ${D.border}`, borderRadius: 12, padding: "18px 20px", flex: 1, minWidth: 130 }}>
      <div style={{ fontSize: 11, color: D.slate3, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.06em", marginBottom: 6 }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 700, color }}>
        {prefix}{num.toLocaleString()}{suffix}
      </div>
    </div>
  );
}

function Chip({ emoji, label, value, tooltip }) {
  const [show, setShow] = useState(false);
  return (
    <div
      onMouseEnter={() => setShow(true)}
      onMouseLeave={() => setShow(false)}
      style={{ position: "relative", background: "rgba(255,255,255,0.15)", backdropFilter: "blur(8px)", border: "1px solid rgba(255,255,255,0.3)", borderRadius: 10, padding: "10px 14px", cursor: "default", minWidth: 110 }}
    >
      <div style={{ fontSize: 18 }}>{emoji}</div>
      <div style={{ fontSize: 11, color: "rgba(255,255,255,0.75)", marginTop: 3, fontWeight: 500 }}>{label}</div>
      <div style={{ fontSize: 13, color: "#fff", fontWeight: 700, marginTop: 1 }}>{value}</div>
      {show && tooltip && (
        <div style={{ position: "absolute", bottom: "calc(100% + 8px)", left: "50%", transform: "translateX(-50%)", background: "#fff", color: D.slate1, borderRadius: 8, padding: "10px 14px", fontSize: 12, width: 200, boxShadow: "0 8px 30px rgba(0,0,0,0.15)", zIndex: 100, borderTop: `3px solid ${D.purple}`, lineHeight: 1.5 }}>
          {tooltip}
        </div>
      )}
    </div>
  );
}

