function MRRChart() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const script = document.createElement("script");
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.js";
    script.onload = () => {
      const months = ["M1","M2","M3","M4","M5","M6","M7","M8","M9","M10","M11","M12"];
      const mrr = [490, 980, 1960, 3430, 5390, 7840, 10290, 12250, 14210, 16170, 18620, 21560];
      new window.Chart(canvasRef.current, {
        type: "line",
        data: {
          labels: months,
          datasets: [{
            label: "MRR ($)",
            data: mrr,
            borderColor: D.purple,
            backgroundColor: D.purple + "18",
            fill: true,
            tension: 0.4,
            pointRadius: 4,
            pointBackgroundColor: D.purple,
          }],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: false },
            tooltip: {
              callbacks: { label: (c) => " $" + c.parsed.y.toLocaleString() + "/mo" },
            },
          },
          scales: {
            y: {
              beginAtZero: true,
              ticks: { callback: (v) => "$" + (v / 1000).toFixed(0) + "k", color: D.slate3, font: { size: 11 } },
              grid: { color: "#f0f0f0" },
            },
            x: { ticks: { color: D.slate3, font: { size: 11 } }, grid: { display: false } },
          },
        },
      });
    };
    document.body.appendChild(script);
  }, []);
  return (
    <div style={{ position: "relative", width: "100%", height: 260 }}>
      <canvas ref={canvasRef} role="img" aria-label="MRR growth chart for InkOS over 12 months, reaching $21,560 by month 12" />
    </div>
  );
}



